head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00015";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultDiv
// TODO Stage2: 세션 키 실환경 확인(회신 11항) — session.user.usrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00015.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "img_33", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "c_when_25", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_26", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_28", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_30", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "c_when_34", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_35", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_37", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_39", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "c_when_41", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_42", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_44", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_46", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "img_56", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "c_when_48", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_49", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_51", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_53", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "c_when_57", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_58", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_60", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_62", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "c_otherwise_64", fn: function(){ return (!(((dma_pageContext.get("resultDiv") ?? "") === '1') || ((dma_pageContext.get("resultDiv") ?? "") === '2') || ((dma_pageContext.get("resultDiv") ?? "") === '3') || ((dma_pageContext.get("resultDiv") ?? "") === '4') || ((dma_pageContext.get("resultDiv") ?? "") === '5'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("transMessage") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_14_onclick
 * @description img_14 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_14_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000021)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00015.img_14_onclick' }); }
};

/**
 * @method
 * @name img_33_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_33_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00015.img_33_onclick' }); }
};

/**
 * @method
 * @name img_56_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_56_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00015.img_56_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goList = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil10100/jldfil10100.xml');
};
